function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30, H/2 + 70);
  ctx.stroke();

  // blessing circles
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + 80 * Math.cos(i + t), H/2 + 50 + 80 * Math.sin(i + t), 10 + 5 * Math.sin(t + i), 0, 2 * Math.PI);
    ctx.stroke();
  }

  // arms up
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30 + 20 * Math.sin(t), H/2 + 30 - 20 * Math.cos(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30 + 20 * Math.sin(t), H/2 + 30 - 20 * Math.cos(t));
  ctx.stroke();

  ctx.restore();
}
